#!/usr/bin/env python3
"""Story -> test traceability matrix (IS212: "test evidence should make it
possible to trace important user stories or acceptance criteria to the
relevant tests").

Reads, without running anything:
  * backend   backend/src/test/**/*Test.java   class-level @Tag("<StoryID>"),
              layer from @Tag("unit") / @Tag("integration")
  * frontend  frontend/src/**/*.test.ts(x)     story IDs in describe/it titles
              and a "// @stories ID ID" header line
  * e2e       frontend/e2e/*.spec.ts           story IDs in test titles/header
AC references ("EC08 AC12") and case types ("(negative)", "(boundary)", ...)
are picked up from test names and display names.

Writes docs/test-traceability.md. With --check, exits 1 if any test file
traces to no story, so new tests cannot silently drop out of the matrix.
With GITHUB_STEP_SUMMARY set (CI), also writes a short summary there.

Usage: python .github/scripts/traceability.py [--check]
"""
import os
import re
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs' / 'test-traceability.md'

STORY = re.compile(r'\b(?:EO|EC|ECL|ELC|VS|TS|AT|AU|DEV|SO)(?:-(?:C|NEW))?\d{1,2}[AB]?\b')
# "EC08 AC7", "EC08 AC7, AC16" and ranges such as "EC-NEW2 AC8–AC12".
AC_REF = re.compile(r'\b((?:EO|EC|ECL|ELC|VS|TS|SO)(?:-(?:C|NEW))?\d{1,2}[AB]?) '
                    r'(AC\d{1,2}(?:\s*(?:,|–|-)\s*AC\d{1,2})*)')


def expand_acs(text):
    """'AC4, AC8–AC12' -> [4, 8, 9, 10, 11, 12]."""
    numbers = []
    for part in re.split(r'\s*,\s*', text):
        bounds = [int(n) for n in re.findall(r'AC(\d+)', part)]
        numbers.extend(range(bounds[0], bounds[1] + 1) if len(bounds) == 2 else bounds)
    return numbers
CASE_TYPES = ('happy', 'negative', 'boundary', 'conflict', 'failure', 'cross-cutting')

# Snapshot of the Sheet's "Prioritised User Stories" High column (2026-10-16).
# Update it when priorities change; it only drives the "gaps" section.
HIGH_PRIORITY = [
    'EO01', 'EO02', 'EO03', 'EO04', 'EO07', 'EO09', 'EO11', 'EO12', 'EO26',
    'EC01', 'EC02', 'EC03', 'EC04', 'EC05', 'EC07', 'EC08', 'EC09', 'EC10',
    'EC-NEW2', 'EC-NEW3', 'EC-NEW4', 'EC-C2', 'EC-C3', 'EC-C4',
    'VS01', 'VS02', 'VS03', 'VS04', 'VS06A', 'VS06B', 'VS08', 'VS-C1', 'VS-C2', 'VS-C3',
    'TS01', 'TS02', 'TS03', 'AT01', 'AT02', 'AT03', 'AT08', 'ECL-C1', 'ECL-C2', 'ECL-C3',
]


def rel(p):
    return p.relative_to(ROOT).as_posix()


def backend_files():
    for p in sorted((ROOT / 'backend/src/test').rglob('*Test.java')):
        s = p.read_text(encoding='utf-8')
        tags = re.findall(r'@Tag\("([^"]+)"\)', s)
        layer = 'integration' if 'integration' in tags else 'unit'
        stories = sorted({t for t in tags if STORY.fullmatch(t)})
        tests = len(re.findall(r'@(?:Test|ParameterizedTest|RepeatedTest)\b', s))
        yield rel(p), 'backend ' + layer, stories, tests, s


def frontend_files():
    for p in sorted((ROOT / 'frontend/src').rglob('*.test.ts*')):
        s = p.read_text(encoding='utf-8')
        yield rel(p), 'frontend component/unit', ids_in(s), count_its(s), s
    for p in sorted((ROOT / 'frontend/e2e').glob('*.spec.ts')):
        s = p.read_text(encoding='utf-8')
        yield rel(p), 'e2e (browser)', ids_in(s), count_its(s), s


def ids_in(source):
    found = set()
    for line in source.splitlines():
        stripped = line.strip()
        if stripped.startswith('// @stories'):
            found.update(STORY.findall(stripped))
        elif re.match(r'^(describe|it|test)(\.\w+)?\(', stripped):
            found.update(STORY.findall(stripped))
    return sorted(found)


def count_its(source):
    return len(re.findall(r'^\s*(?:it|test)(?:\.each\([^)]*\))?\(', source, re.M))


def main():
    check = '--check' in sys.argv
    rows = list(backend_files()) + list(frontend_files())
    by_story = defaultdict(lambda: {'files': defaultdict(list), 'acs': set(), 'cases': set(), 'tests': 0})
    untraced = []
    for path, layer, stories, tests, source in rows:
        if not stories:
            untraced.append(path)
        for story in stories:
            entry = by_story[story]
            entry['files'][layer].append(path)
            entry['tests'] += tests
        for story, acs in AC_REF.findall(source):
            by_story[story]['acs'].update(expand_acs(acs))
        for story in stories:
            for case in CASE_TYPES:
                if re.search(r'\(' + re.escape(case) + r'\)', source):
                    by_story[story]['cases'].add(case)

    layers_order = ['backend unit', 'backend integration', 'frontend component/unit', 'e2e (browser)']
    lines = [
        '# Test traceability matrix',
        '',
        'Generated by `python .github/scripts/traceability.py` from the test sources. Do not edit by hand.',
        'Each story lists the test files that exercise it, by layer (IS212 Week 4/6/9 test pyramid).',
        '"ACs referenced" are acceptance criteria named in test names (e.g. `EC08 AC12`); the full',
        'AC-by-AC mapping for a story, with its Week 4 test cases, lives in `docs/test-cases/`.',
        '',
        f'**{len(rows)} test files, {sum(r[3] for r in rows)} tests, {len(by_story)} stories traced, '
        f'{len(untraced)} files untraced.**',
        '',
        '| Story | Unit (BE) | Integration (BE) | Component (FE) | E2E | Tests | ACs referenced | Case types named |',
        '|---|---:|---:|---:|---:|---:|---|---|',
    ]

    def key(s):
        m = re.match(r'([A-Z]+)(-[A-Z]+)?(\d+)', s)
        return (m.group(1), m.group(2) or '', int(m.group(3))) if m else (s, '', 0)

    for story in sorted(by_story, key=key):
        e = by_story[story]
        counts = [len(e['files'].get(layer, [])) for layer in layers_order]
        acs = ', '.join(f'AC{a}' for a in sorted(e['acs'])) or '—'
        cases = ', '.join(c for c in CASE_TYPES if c in e['cases']) or '—'
        lines.append(f'| {story} | ' + ' | '.join(str(c) if c else '' for c in counts)
                     + f" | {e['tests']} | {acs} | {cases} |")

    gaps = [s for s in HIGH_PRIORITY if s not in by_story]
    lines += ['', '## High-priority stories with no automated test yet', '']
    lines += [f'- {s}' for s in gaps] or ['- none']
    lines += ['', 'Some of these are not built yet; a story that is built and still listed here needs tests.',
              '', '## Untraced test files', '']
    lines += [f'- `{u}`' for u in untraced] or ['- none']
    lines += ['', '## Files per story', '']
    for story in sorted(by_story, key=key):
        lines.append(f'<details><summary>{story}</summary>\n')
        for layer in layers_order:
            for f in by_story[story]['files'].get(layer, []):
                lines.append(f'- {layer}: `{f}`')
        lines.append('\n</details>')
    OUT.write_text('\n'.join(lines) + '\n', encoding='utf-8')

    summary = (f'### Traceability\n{len(rows)} test files, {len(by_story)} stories traced, '
               f'{len(untraced)} untraced files, {len(gaps)} High-priority stories without tests.\n')
    if os.environ.get('GITHUB_STEP_SUMMARY'):
        with open(os.environ['GITHUB_STEP_SUMMARY'], 'a', encoding='utf-8') as f:
            f.write(summary)
    print(summary.strip())
    if check and untraced:
        print('Untraced test files (add a story @Tag / "// @stories" header):', *untraced, sep='\n  ')
        sys.exit(1)


if __name__ == '__main__':
    main()
